+    const WHEEL_DOWN = '\x1b[<65;1;1M'; // See newer content (scroll down in history)
+
+    it('wheel UP escape sequence format is correct', () => {
+      expect(WHEEL_UP).toBe('\x1b[<64;1;1M');
