+      expect(WHEEL_UP.startsWith('\x1b[<')).toBe(true);
+      // Button 64 for wheel up
+      expect(WHEEL_UP.includes('64')).toBe(true);
+    });
+
+    it('wheel DOWN escape sequence format is correct', () => {
+      expect(WHEEL_DOWN).toBe('\x1b[<65;1;1M');
