+      // - Swipe DOWN (positive deltaY) → content moves down → see OLDER content → wheel UP
+      const getWheelEventForDelta = (deltaY: number): string => {
+        return deltaY < 0 ? WHEEL_DOWN : WHEEL_UP;
+      };
